import{z as n,x as A,o as t,c as d,q as l,j as s,D as E,d as e,s as B,S as o,b as r}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"SDL","description":"","frontmatter":{"title":"SDL","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sdl-lifecycle.md","filePath":"cs/sdl-lifecycle.md","lastUpdated":1791413859000}'),c={name:"cs/sdl-lifecycle.md"};function p(D,a,C,m,h,f){const i=A("Mermaid");return t(),d("div",null,[a[2]||(a[2]=l('<h1 id="sdl" tabindex="-1">SDL <a class="header-anchor" href="#sdl" aria-label="Permalink to &quot;SDL&quot;">​</a></h1><div class="epigraph"><p>安全开发生命周期把威胁建模、设计审查、工具门禁、事件响应写进版本列车。它是过程控制，不是一次扫描。微软 SDL 是公开的工程模板之一。</p><footer>—— Howard and Lipner, *The Security Development Lifecycle*；Microsoft SDL；对照 McGraw</footer></div><p>上一课<a href="/cs/tcb-minimization">TCB</a>要求信任基可审；缺口是<strong>组织如何持续生产较小的 TCB</strong>——答案是写进发布过程：门禁。本课 SDL。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>没有安全活动的发布火车会持续回归：每批新功能把旧缺口重开一遍。缺口是在四个位置插入活动——需求阶段做威胁模型，把「信任谁、防谁」写成设计约束；编译与测试挂 sanitizer 和静态分析当门禁；依赖进 SBOM 审查；发布前过就绪检查，事件响应留轮值。<span class="marginnote">门禁可以类比机场安检：不是起飞前才查一次，而是每个登机口都设一道——代码每过一次构建就被查一遍，「带病提交」在合并前就被拦下。SDL 的全部主张，是把「查没查」从个人自觉变成流水线结构。</span></p><h3 id="度量" tabindex="-1">度量 <a class="header-anchor" href="#度量" aria-label="Permalink to &quot;度量&quot;">​</a></h3><p>度量要接住风险：漏洞密度与平均修复时间是过程健康指标；一旦直接当 KPI 考核，就会被「少报漏洞、关单求快」优化掉，变成虚荣指标。<span class="marginnote">这是古德哈特定律的教科书案例：指标一旦成为考核目标，就会被优化指标本身而非它代表的东西——团队学会少报不修，密度「下降」而风险上升。正确读法是把密度与修复时间当健康趋势看，考核对象放在「门禁是否真的在跑」这类过程事实上。</span></p><p><span class="marginnote">Howard–Lipner。seL4 下一课是另一极端：形式验证微内核。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把课程已讲的活动按阶段插上火车：fuzz 挂测试，代码审查挂合并，SBOM 挂依赖准入，事件响应挂运维轮值。SDL 的主张是过程控制——门禁随每次构建自动执行，不是发布前的一次性扫描。下一课 seL4 封课程。</p>',11)),(t(),s(o,null,{default:E(()=>[B(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E9%9C%80%E6%B1%82%E5%A8%81%E8%83%81%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20DES%5B%22%E8%AE%BE%E8%AE%A1%E5%AE%A1%E6%9F%A5%22%5D%0A%20%20DES%20--%3E%20IMP%5B%22%E5%B7%A5%E5%85%B7%E9%97%A8%E7%A6%81%22%5D%0A%20%20IMP%20--%3E%20REL%5B%22%E5%B0%B1%E7%BB%AA%E4%B8%8E%E5%93%8D%E5%BA%94%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[e("SDL 的机制是把课程钉下的合同物化成列车上的门：威胁模型变成设计审查清单，sanitizer 变成合并门禁，SBOM 变成依赖准入。每道门把一类错误挡在发布之前；过程输出可审计，组织知识不随人员流动丢失。它不证明代码正确，只保证错误必须过门。形式验证下一课把微内核收到可机检证明。"),r("span",{class:"marginnote"},"术语翻译：SDL 就是用「把安全活动变成不可跳过的门」的手段来做「让 TCB 不随功能迭代悄悄变大」的事——每批新功能想进主干，必须先证明自己没把旧缺口重开一遍。")],-1)),(t(),s(o,null,{default:E(()=>[B(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20MR%5B%22%E6%8F%90%E4%BA%A4%E4%BB%A3%E7%A0%81%20%2F%20%E5%BC%95%E5%85%A5%E6%96%B0%E4%BE%9D%E8%B5%96%22%5D%20--%3E%20G1%7B%22%E9%9D%99%E6%80%81%E5%88%86%E6%9E%90%E4%B8%8E%EF%BC%9Cbr%2F%EF%BC%9Esanitizer%20%E9%80%9A%E8%BF%87%3F%22%7D%0A%20%20G1%20--%3E%7C%22%E5%90%A6%22%7C%20REJ1%5B%22%E6%8C%A1%E5%9C%A8%E5%90%88%E5%B9%B6%E9%97%A8%E7%A6%81%22%5D%0A%20%20G1%20--%3E%7C%22%E6%98%AF%22%7C%20G2%7B%22SBOM%20%E5%AE%A1%E6%9F%A5%EF%BC%9A%EF%BC%9Cbr%2F%EF%BC%9E%E4%BE%9D%E8%B5%96%E6%9C%89%E5%B7%B2%E7%9F%A5%E6%BC%8F%E6%B4%9E%3F%22%7D%0A%20%20G2%20--%3E%7C%22%E6%9C%89%22%7C%20REJ2%5B%22%E6%8C%A1%E5%9C%A8%E4%BE%9D%E8%B5%96%E5%87%86%E5%85%A5%22%5D%0A%20%20G2%20--%3E%7C%22%E9%80%9A%E8%BF%87%22%7C%20REL%5B%22%E5%8F%91%E5%B8%83%E5%89%8D%E5%B0%B1%E7%BB%AA%E6%A3%80%E6%9F%A5%22%5D%0A%20%20REL%20--%3E%20VULN%5B%22%E4%B8%8A%E7%BA%BF%E5%90%8E%E4%BB%8D%E5%8F%91%E7%8E%B0%E6%BC%8F%E6%B4%9E%22%5D%0A%20%20VULN%20--%3E%20IR%5B%22%E4%BA%8B%E4%BB%B6%E5%93%8D%E5%BA%94%E8%BD%AE%E5%80%BC%E6%8E%A5%E5%8D%95%3Cbr%2F%3E%E4%BF%AE%E5%A4%8D%E6%97%B6%E9%97%B4%E8%AE%B0%E5%85%A5%E5%BA%A6%E9%87%8F%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把 SDL 写成官僚表格：每道检查项都要能说出它挡住的失效模式，说不出的一项就是纯开销。seL4 形式验证下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TCB 要过程才能保持小。</li><li>威胁模型到门禁到响应是闭环。</li><li>工具是门，不是一次性扫描。</li><li>下一课 seL4 形式验证。</li><li>出处：Howard and Lipner；Microsoft SDL；McGraw。</li></ul>',4))])}const u=n(c,[["render",p]]);export{L as __pageData,u as default};
